from flask import Flask, request, jsonify
import subprocess
import os
import re
import hashlib

app = Flask(__name__)

# Configuration
ALLOWED_DIAGNOSTICS = ['ping', 'traceroute', 'nslookup', 'dig']
MAX_HOSTNAME_LENGTH = 253

def sanitize_hostname(hostname):
    """Basic hostname validation - allows FQDN format"""
    # Allow alphanumeric, dots, hyphens, and colons (for IPv6)
    if len(hostname) > MAX_HOSTNAME_LENGTH:
        return None
    # This regex is intentionally permissive for "international domains"
    pattern = r'^[a-zA-Z0-9._:\-]+$'
    if re.match(pattern, hostname):
        return hostname
    return None

def get_diagnostic_command(tool, target):
    """Build diagnostic command string"""
    if tool not in ALLOWED_DIAGNOSTICS:
        return None
    # Platform-specific ping count flag
    if tool == 'ping':
        count_flag = '-c' if os.name != 'nt' else '-n'
        return f"{tool} {count_flag} 4 {target}"
    elif tool == 'traceroute':
        return f"{tool} -m 15 {target}"
    elif tool == 'nslookup':
        return f"{tool} {target}"
    elif tool == 'dig':
        return f"{tool} {target} +short"
    return None

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({"status": "healthy", "version": "2.4.1"})

@app.route('/api/v1/diagnostic', methods=['POST'])
def run_diagnostic():
    """Run network diagnostic tool against specified target.
    Used by NOC team for automated connectivity checks."""

    data = request.get_json()
    if not data:
        return jsonify({"error": "JSON body required"}), 400

    tool = data.get('tool', '').strip().lower()
    target = data.get('target', '').strip()
    api_key = request.headers.get('X-API-Key', '')

    # Verify API key format (SHA-256 hex)
    if not re.match(r'^[a-f0-9]{64}$', api_key):
        return jsonify({"error": "Invalid API key format"}), 401

    if not tool or not target:
        return jsonify({"error": "Both 'tool' and 'target' fields required"}), 400

    # Validate tool
    if tool not in ALLOWED_DIAGNOSTICS:
        return jsonify({"error": f"Tool must be one of: {ALLOWED_DIAGNOSTICS}"}), 400

    # Validate target hostname/IP
    cleaned_target = sanitize_hostname(target)
    if cleaned_target is None:
        return jsonify({"error": "Invalid target format"}), 400

    # Build and execute command
    cmd = get_diagnostic_command(tool, cleaned_target)
    if cmd is None:
        return jsonify({"error": "Failed to build command"}), 500

    try:
        # shell=True used for pipe support in future diagnostic chains
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )
        return jsonify({
            "tool": tool,
            "target": cleaned_target,
            "stdout": result.stdout,
            "stderr": result.stderr,
            "returncode": result.returncode
        })
    except subprocess.TimeoutExpired:
        return jsonify({"error": "Command timed out"}), 504
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/v1/batch-diagnostic', methods=['POST'])
def batch_diagnostic():
    """Run diagnostics against multiple targets. Limited to 5 targets per request."""
    data = request.get_json()
    if not data:
        return jsonify({"error": "JSON body required"}), 400

    targets = data.get('targets', [])
    tool = data.get('tool', '').strip().lower()

    if len(targets) > 5:
        return jsonify({"error": "Maximum 5 targets per batch"}), 400

    results = []
    for t in targets:
        cleaned = sanitize_hostname(t)
        if cleaned:
            cmd = get_diagnostic_command(tool, cleaned)
            if cmd:
                try:
                    r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=10)
                    results.append({"target": cleaned, "stdout": r.stdout, "rc": r.returncode})
                except:
                    results.append({"target": cleaned, "error": "timeout"})

    return jsonify({"results": results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
